import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  template: `
    <div>
      <span *ngFor="let star of [].constructor(maxStars); let i = index" (click)="setRating(i + 1)">
        {{ i < rating ? '★' : '☆' }}
      </span>
    </div>
  `
})
export class StarRatingComponent {
  @Input() rating: number = 0;
  @Input() maxStars: number = 5;
  @Output() ratingChanged = new EventEmitter<number>();

  setRating(value: number) {
    this.rating = value;
    this.ratingChanged.emit(value);
  }
}

import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  template: `
    <div>
      <span *ngFor="let star of [].constructor(maxStars); let i = index" (click)="setRating(i + 1)" [class.filled]="i < rating">
        {{ i < rating ? '★' : '☆' }}
      </span>
    </div>
  `
})
export class StarRatingComponent {
  @Input() rating: number = 0;
  @Input() maxStars: number = 5;
  @Output() ratingChanged = new EventEmitter<number>();

  setRating(value: number) {
    this.rating = value;
    this.ratingChanged.emit(value);
  }
}
